//package practice.E;

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class CF295C_ {

    static int[][][] dp1;
    static int[][][][] dp2;
    static int k;
    static int mod = 1000000007;
    static int F, H;
    static boolean[][][] vis;

    public static void main(String[] args) throws IOException {
        CF295C.Scanner sc = new CF295C.Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt();
        k = sc.nextInt();
        for (int i = 0; i < n; i++) {
            if(sc.nextInt() == 50)
                F++;
            else
                H++;
        }

        comb = new long[100][100];
        for (int i = 0; i < comb.length; i++) {
            Arrays.fill(comb[i], -1);
        }
        dp1 = new int[2][51][51];
        for (int i = 0; i < dp1.length; i++) {
            for (int j = 0; j < dp1[i].length; j++) {
                Arrays.fill(dp1[i][j], -1);
            }
        }
        vis = new boolean[2][51][51];
        comb = new long[100][100];
        for (int i = 0; i < comb.length; i++) {
            Arrays.fill(comb[i], -1);
        }
        int min = solve(F, H, 0);
        if(min > 100000){
            System.out.println(-1);
            System.out.println(0);
            return;
        }


        dp2 = new int[2][51][51][min+1];
        for (int i = 0; i < vis.length; i++) {
            for (int j = 0; j < vis[i].length; j++) {
                Arrays.fill(vis[i][j], false);
            }
        }
        for (int i = 0; i < dp2.length; i++) {
            for (int j = 0; j < dp2[i].length; j++) {
                for (int l = 0; l < dp2[i][j].length; l++) {
                    Arrays.fill(dp2[i][j][l], -1);
                }
            }
        }

        System.out.println(min);
//        System.out.println(solve2(0, F, H, min));
        System.out.println(solve2(F, H, 0, min));

        pw.flush();
        pw.close();
    }

    static int solve(int fifty, int hundred, int side){
        if(fifty + hundred == 0 && side == 0)
            return 0;
        if(fifty == F && hundred == H && side == 1)
            return 0;
        if(dp1[side][fifty][hundred] != -1)
            return dp1[side][fifty][hundred];
        if(vis[side][fifty][hundred])
            return 1000000000;
        vis[side][fifty][hundred] = true;
        int ans = 1000000000;
        for (int ff = 0; ff <= fifty; ff++)
            for (int hh = 0; hh <= hundred; hh++) {
                if(hh + ff == 0 || hh*100+ff*50 > k)
                    continue;
                ans = Math.min(ans, 1 + solve(F-fifty+ff, H-hundred+hh, 1^side));
            }

        return dp1[side][fifty][hundred] = ans;
    }

    static int solve2(int fifty, int hundred, int side, int min){
        if(min < 0)
            return 0;
        if(fifty + hundred == 0 && side == 0)
            if(min == 0)
                return 1;
        if(fifty == F && hundred == H && side == 1)
            if(min == 0)
                return 1;
        if(min == 0)
            return 0;
        if(dp2[side][fifty][hundred][min] != -1)
            return dp2[side][fifty][hundred][min];
        int ans = 0;
        for (int ff = 0; ff <= fifty; ff++)
            for (int hh = 0; hh <= hundred; hh++) {
                if(hh + ff == 0 || hh*100+ff*50 > k)
                    continue;
//                if(1 + solve(F-fifty+ff, H-hundred+hh, 1^side) == solve(fifty, hundred, side))
                    ans = (int)((ans + (((1l*nCr1(fifty, ff)*nCr1(hundred, hh)%mod)*solve2(F-fifty+ff, H-hundred+hh, 1^side, min-1))%mod))%mod);
            }

        return dp2[side][fifty][hundred][min] = ans;
    }



    static long[][] comb;

    static long nCr1(int n , int k)
    {
        if(n < k)
            return 0;
        if(k == 0 || k == n)
            return 1;
        if(comb[n][k] != -1)
            return comb[n][k];
        if(n - k < k)
            return comb[n][k] = nCr1(n, n - k);
        return comb[n][k] = (nCr1(n - 1, k - 1) + nCr1(n - 1, k)) % mod;
    }

    static class Scanner
    {
        StringTokenizer st; BufferedReader br;
        public Scanner(InputStream s){	br = new BufferedReader(new InputStreamReader(s));}
        public Scanner(String s) throws FileNotFoundException {	br = new BufferedReader(new FileReader(new File(s)));}
        public String next() throws IOException {while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());return st.nextToken();}
        public int nextInt() throws IOException {return Integer.parseInt(next());}
        public long nextLong() throws IOException {return Long.parseLong(next());}
        public String nextLine() throws IOException {return br.readLine();}
        public boolean ready() throws IOException {return br.ready();}
    }
}

